window.EXCHANGE_ATLAS_GUIDES = {"campuses":{"BER":{"setting":"metro","transit":"Lichtenberg Campus has U5 Friedrichsfelde, S-Bahn Friedrichsfelde and buses 108, 194 and N5; the Deutschlandsemesterticket covers local transport.","city":"Berlin combines major museums, nightlife and multicultural neighbourhoods; Lichtenberg is next to Tierpark Berlin and Friedrichsfelde Palace.","food":"Currywurst, Berliner döner, Bouletten; affordable: currywurst or döner from an Imbiss.","activities":"Tierpark Berlin, Friedrichsfelde Palace, Museum Island.","visitUrl":"https://www.visitberlin.de/en","visitExtra":"https://www.berlin.de/en","english":"limited","englishNote":"The Computer Science Berlin Study Plus exchange format offers an English Stream, but the main teaching language is German; current Lichtenberg exchange English is documented for Law, Public Management and Security Management, not computing.","englishUrl":"https://www.hwr-berlin.de/hwr-berlin/fachbereiche-und-zentralinstitute/fb-2-duales-studium/studieren-am-fachbereich/austauschprogramme/","gallery":"https://www.hwr-berlin.de/en/study/studying-at-the-hwr-berlin/starting-your-studies","photo":{"src":"assets/campuses/ber.webp","caption":"HWR Berlin, Schöneberg campus. Computer Science is associated with Lichtenberg.","source":"https://commons.wikimedia.org/wiki/File:Berlin_Hochschule_f%C3%BCr_Wirtschaft_und_Recht_Berlin_lub_2026-01-10_img01_Campus_Sch%C3%B6neberg.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","author":"Lukas Beck","width":525,"height":700}},"DEG":{"setting":"town","transit":"The main campus is walkable from town; Deggendorf station is about 20 minutes on foot, or buses 1, 2 and 3 connect station and campus; Waldbahn serves the station.","city":"A compact Danube town beside the Bavarian Forest, with a medieval centre, riverside promenade and student-friendly cafés and pubs.","food":"Deggendorfer dumplings, roast pork with dumplings, Brotzeit with Brezen and Obazda; affordable: Mensa or supermarket Brotzeit.","activities":"Danube cycling or cruise, Bavarian Forest hiking, Deggendorf Cultural Quarter and Handwerksmuseum.","visitUrl":"https://deggendorf.travel/","visitExtra":"https://www.deggendorf.de/sprachen/englisch/welcome","english":"confirmed","englishNote":"DIT exchange students may take English-taught Computer Science courses; named computing examples include Applied Computer Science, Artificial Intelligence and Data Science, Advanced Data Storage and Analyses, Parallel Programming and Computing, and the entirely English MSc Applied Computer Science.","englishUrl":"https://www.th-deg.de/exchange-students#course-choices","gallery":"https://ec.dit.edu/deggendorf-en","photo":{"src":"assets/campuses/deg.webp","caption":"Deggendorf Institute of Technology main campus.","source":"https://commons.wikimedia.org/wiki/File:Hauptcampus_der_Technischen_Hochschule_Deggendorf_2018.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Danube-Waidler","width":960,"height":221}},"DE1":{"setting":"town","transit":"Bus line 6 runs from Fulda ZOB beside the railway station toward the university; the campus is also 15–20 minutes on foot from the station.","city":"Fulda is a compact baroque university town with a cathedral quarter, lively pubs and quick access to Rhön nature.","food":"Rhön regional sausage, seasonal regional dishes, homemade cakes; affordable: university Mensa or weekly-market food.","activities":"Fulda Cathedral and baroque quarter, Wasserkuppe hiking or tobogganing, River Fulda canoeing.","visitUrl":"https://www.tourismus-fulda.de/en","visitExtra":"https://www.tourismus-fulda.de/en/plan/arrival-transport","english":"confirmed","englishNote":"The incoming English list names Applied Computer Science Test-Oriented Development, 5 credits, winter semester; the university requires B2 English for English-taught courses.","englishUrl":"https://www.hs-fulda.de/en/international/international-students/exchange-students-incoming/courses-taught-in-english","gallery":"https://www.hs-fulda.de/en/university-of-applied-sciences/this-is-us/campus","photo":{"src":"assets/campuses/de1.webp","caption":"Fulda University of Applied Sciences campus.","source":"https://commons.wikimedia.org/wiki/File:Hochschule_Fulda_2025-08-31_01.jpg","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","author":"Leonhard Lenz","width":960,"height":639}},"HKA":{"setting":"city","transit":"HKA main campus is served by KVV trams: line 2 or 3 to Europaplatz/Postgalerie, or line 1 from Marktplatz to Kunstakademie/Hochschule.","city":"Karlsruhe is a fan-shaped, green city; HKA sits centrally west of the palace grounds and beside Hardtwald.","food":"Badische cuisine, Maultaschen, regional beer; affordable: HKA/Mensa or a snack at Menseria Schloss Gottesaue.","activities":"Karlsruhe Palace and gardens, ZKM, Durlach old town and Turmberg.","visitUrl":"https://www.karlsruhe-erleben.de/en","visitExtra":"https://www.karlsruhe.dhbw.de/en/exchange-students/student-life/activities-in-karlsruhe.html","english":"confirmed","englishNote":"HKA exchange students can take English courses through the International Program; its medium of instruction and assessment is English, with courses from General Studies and individual degree programs, including computer-science-related offerings in the course catalogue.","englishUrl":"https://www.h-ka.de/en/exchange-students","gallery":"https://www.h-ka.de/en/about-hka/campuses","photo":{"src":"assets/campuses/hka.webp","caption":"Karlsruhe University of Applied Sciences.","source":"https://commons.wikimedia.org/wiki/File:Hochschule_Karlsruhe.JPG","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","author":"Voskos","width":933,"height":700}},"LW":{"setting":"city","transit":"The 2026 exchange fact sheet identifies a Deutschlandticket usable on suburban trains, trams and buses throughout Germany; the campus address is Ernst-Boehe-Straße 4–6.","city":"Ludwigshafen sits opposite Mannheim in the Rhine-Neckar metropolitan region, with Palatinate vineyards, festivals and modern art nearby.","food":"Saumagen, Winzersteak, Palatinate wine; affordable: HWG Mensa five-component meal or cafeteria sandwich.","activities":"Wilhelm-Hack-Museum, Festival of German Film on Parkinsel, Rhine promenade and Mannheim across the river.","visitUrl":"https://www.hwg-lu.de/en/university/city-and-region","visitExtra":"https://www.wilhelmhack.museum/en/your-visit/contact-and-drive","english":"limited","englishNote":"The winter 2026/27 list includes English for IT and business-informatics communication. It provides evidence of technical language teaching. Confirm whether technical computing modules are taught in English.","englishUrl":"https://www.hwg-lu.de/fileadmin/user_upload/Extranet__Homepage/Dokumente/Abteilungen/Internationales/Incomings/Classes_in_English_WS2627.pdf","gallery":"https://www.hwg-lu.de/hochschule/organisation/hochschulkommunikation/news-pressemitteilungen/die-hwg-lu-entdecken-mit-der-virtual-reality-tour","photo":{"src":"assets/campuses/lw.webp","caption":"Ludwigshafen University of Business and Society campus.","source":"https://commons.wikimedia.org/wiki/File:HWG_Ludwigshafen_(6).jpg","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","author":"Immanuel Giel","width":933,"height":700}},"OSN":{"setting":"city","transit":"Westerberg stops are Botanischer Garten on line 16 and Campus Westerberg on lines M2, 16 and S10; VOS is the local bus network.","city":"Osnabrück is a student city where Westerberg combines laboratories, a botanical garden, cafés and nearby woods with a walkable historic centre.","food":"Pumpernickel, regional sausage, farmers-market produce; affordable: Westerberg Mensa or Café Lounge snacks.","activities":"Osnabrück Old Town and Peace Hall, Botanical Garden, Piesberg or Rubbenbruchsee; May Week and Terrassenfest are student highlights.","visitUrl":"https://erleben.osnabrueck.de/en/experience-city/study/student-life","visitExtra":"https://erleben.osnabrueck.de/en/experience-city/worth-seeing","english":"limited","englishNote":"The Faculty of Engineering and Computer Science states that German and English are the main teaching languages, but module choice determines the required language; the incoming page names the English-language International Computer Science Program without listing individual computing modules.","englishUrl":"https://www.hs-osnabrueck.de/en/study/international/international-courses-and-programs","gallery":"https://www.hs-osnabrueck.de/en/study/student-life/campus/campus-westerberg","photo":{"src":"assets/campuses/osn.webp","caption":"Engineering and Computer Science faculty, Westerberg campus in Osnabrück.","source":"https://commons.wikimedia.org/wiki/File:Geb%C3%A4ude_Fakult%C3%A4t_IuI,_Albrechtstra%C3%9Fe.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","author":"Hsstudi","width":960,"height":639}},"DE2":{"setting":"town","transit":"Campus Gummersbach is beside Bf. Gummersbach on regional train RB 25; local buses also stop at the station.","city":"Gummersbach is a green, hilly Oberbergisch town with the Steinmüller grounds, Halle 32 and easy access to reservoirs and forests.","food":"Bergische Kaffeetafel, regional hearty cuisine, Kölsch; affordable: döner or a simple Brauhaus meal.","activities":"Aggertalsperre, Genkeltalsperre, historic city tour and Bergisches Land hiking.","visitUrl":"https://www.gummersbach.de/de/hier-zu-gast/ausflugsziele-und-aktivitaeten.html","visitExtra":"https://www.gummersbach.de/de/hier-zu-gast/ausflugsziele-und-aktivitaeten/sehenswuerdigkeiten/talsperren.html","english":"limited","englishNote":"English-language Digital Sciences and Information Systems offerings are documented at master’s level. Ask TH Köln for the separate undergraduate exchange module list.","englishUrl":"https://www.th-koeln.de/en/academics/digital-sciences-masters-program_83005.php","gallery":"https://www.th-koeln.de/en/gummersbach-campus_76531.php","photo":{"src":"assets/campuses/de2.webp","caption":"TH Köln, Campus Gummersbach.","source":"https://commons.wikimedia.org/wiki/File:THKoelnCampusGummersbachWithSign.jpeg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","author":"Benutzer:MDXDave","width":960,"height":640}},"DE3":{"setting":"city","transit":"From Gießen station, bus line 2 reaches Berliner Platz or line 5 reaches Behördenzentrum/Landgericht; each is about a four-minute walk from campus.","city":"Gießen is a lively university city split by the Lahn, with museums, botanical gardens, student nightlife and extensive cycling.","food":"Regional pub food, coffee and cake, Mensa vegetarian/vegan meals; affordable: THM Mensa or CampusTor snacks.","activities":"Mathematikum, Liebig Museum, Botanical Garden and Schiffenberg Abbey.","visitUrl":"https://en.hessen-tourismus.de/where-to-go/towns-and-cities/giessen","visitExtra":"https://www.thm.de/site/en/international/incoming-routes-to-the-thm/exchange-students/discover","english":"confirmed","englishNote":"The THM exchange catalogue lists Information and Data Management, 6 ECTS, Gießen, English, and Distributed Systems, 6 ECTS, Gießen, English friendly; it also states that THInC permits up to 30 ECTS per semester in English.","englishUrl":"https://www.thm.de/site/en/international/incoming-routes-to-the-thm/exchange-students/course-catalogue.html","gallery":"https://www.thm.de/site/en/college/campus/giessen-campus/wayfinding-system-on-the-giessen-campus.html","photo":{"src":"assets/campuses/de3.webp","caption":"Aerial view of TH Mittelhessen in Gießen.","source":"https://commons.wikimedia.org/wiki/File:Luftbild_der_Technischen_Hochschule_Mittelhessen_in_Gie%C3%9Fen._-_panoramio.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","author":"Sascha Endlicher, M.A.","width":933,"height":700}},"ES1":{"setting":"metro","transit":"Intercity buses 623, 626 and 627 serve the UCJC entrance; lines 626A, 641, 642 and 643 serve the urbanisation.","city":"Villafranca is a green, low-density Madrid suburb; Madrid centre is roughly 25 km away, so student life combines quiet campus living with easy metropolitan access.","food":"No specific Villafranca local-food evidence examined; affordable idea: Madrid tapas or a university cafeteria not examined.","activities":"No specific local activity evidence examined; Madrid attractions were not examined in an official destination source.","visitUrl":"https://villafrancadelcastillo.es/en/our-community/very-close-to-everything","visitExtra":"https://www.ucjc.edu/en/campus/","english":"unverified","englishNote":"UCJC evidence confirms Computer Engineering and says courses are offered in English, but no individual English computing course or English-track computing catalogue was verified; a partner fact sheet states the main instruction language is Spanish.","englishUrl":"https://www.ucjc.edu/en/academic-offer","gallery":"https://www.ucjc.edu/en/campus/","photo":{"src":"assets/campuses/es1.webp","caption":"UCJC MediaLab, Villafranca campus.","source":"https://commons.wikimedia.org/wiki/File:MediaLab_Universidad_Camilo_Jos%C3%A9_Cela.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Dcarolina.2000","width":933,"height":700}},"UNE":{"setting":"city","transit":"Santander Urban Transport (TUS) provides city buses; rechargeable cards are available. TUeBICI electric bicycles are another everyday option.","city":"Santander is a compact coastal university city with a walkable centre, beaches, maritime heritage and contemporary culture around Centro Botín.","food":"Rabas, maganos and clams marinara; affordable idea: pinchos around the centre or Barrio Pesquero.","activities":"Magdalena Peninsula, Centro Botín and Cabo Mayor Lighthouse; the official tourism site also highlights the Maritime Museum and bay transport.","visitUrl":"https://turismo.santander.es/en/organising-your-journey/getting-around-santander","visitExtra":"https://turismo.santander.es/en/what-to-do/santander-in-days","english":"limited","englishNote":"The official English course catalogue lists Engineering subjects such as Business Organisation, while Computer Engineering itself lists compulsory English II, III and IV; the evidence does not establish English-taught computing lectures for incoming students.","englishUrl":"https://www.uneatlantico.es/en/office-of-international-relations/subjects-taught-in-english","gallery":"https://www.uneatlantico.es/oficina-de-relaciones-internacionales/santander-en-imagenes","photo":{"src":"assets/campuses/une.webp","caption":"Universidad Europea del Atlántico in Santander.","source":"https://commons.wikimedia.org/wiki/File:Universidad_Europea_del_Atl%C3%A1ntico_(UNEATLANTICO).jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Piajeno","width":960,"height":640}},"ES2":{"setting":"city","transit":"The Albacete campus is near Avenida de España; the city has urban and interurban buses and is described as walkable and accessible.","city":"Albacete is a flat, walkable regional city known for cutlery, modernist architecture, a large September fair and student-oriented central districts.","food":"Gazpacho manchego, atascaburras and migas ruleras; affordable idea: tapas around Plaza del Altozano.","activities":"Municipal Cutlery Museum, Pasaje de Lodares and Abelardo Sánchez Park; the September Feria de Albacete is a major student-friendly event.","visitUrl":"https://www.spain.info/en/destination/albacete","visitExtra":"https://www.uclm.es/misiones/lauclm/campus/campusab","english":"confirmed","englishNote":"The official 2022/23 English-subject list names Autonomous Robotics and Web and Services Engineering in Computer Science and Engineering, Albacete. Availability for 2026/27 must be rechecked.","englishUrl":"https://www.uclm.es/en/misiones/internacional/oferta-internacional/oferta_academica_uclm","gallery":"https://www.uclm.es/misiones/lauclm/campus/campusab","photo":{"src":"assets/campuses/es2.webp","caption":"UCLM’s main assembly hall on the Albacete campus.","source":"https://commons.wikimedia.org/wiki/File:Paraninfo_de_la_Universidad_de_Castilla-La_Mancha._Albacete.jpg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","author":"Gobierno de Castilla-La Mancha","width":960,"height":640}},"UJA":{"setting":"city","transit":"Las Lagunillas has bus stops linking it with central Jaén; UJA lists city buses 4, 7, 9, 12, 14 and 17 from the centre.","city":"Jaén is an inland Andalusian city shaped by olive cultivation, Renaissance architecture and the coexistence of Christian, Jewish and Moorish heritage.","food":"Pipirrana, andrajos and ochíos; affordable idea: tapas bars, where a drink commonly comes with a small tapa.","activities":"Jaén Cathedral, Arab Baths and Santa Catalina Castle; an olive-oil tasting is a distinctive low-cost cultural activity.","visitUrl":"https://www.andalucia.org/en/places-to-visit/jaen/jaen","visitExtra":"https://www.ujaen.es/internacional/en/prepare-your-stay-uja","english":"limited","englishNote":"The PATIE scheme documents English support for computing units such as Human–Computer Interaction. Delivery varies by PATIE level and year. Confirm full English instruction for an individual module.","englishUrl":"https://www.ujaen.es/internacional/en/internacional/informacion-academica/asignaturas-en-otros-idiomas","gallery":"https://www.ujaen.es/la-universidad/los-campus","photo":{"src":"assets/campuses/uja.webp","caption":"Zabaleta Building D1, Las Lagunillas campus in Jaén.","source":"https://commons.wikimedia.org/wiki/File:Edificio_Zabaleta,_edificio_D1,_Universidad_de_Ja%C3%A9n,_Ja%C3%A9n,_Espa%C3%B1a,_2014.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Benjamín Núñez González","width":933,"height":700}},"ULPGC":{"setting":"metro","transit":"Tafira is served by Guaguas Municipales lines 7, 25, 26 and 48, plus Global lines 026, 301, 302, 303, 311, 313, 323, 324, 325, 327 and 328.","city":"Las Palmas combines Atlantic-city life, historic Vegueta and Triana, year-round beaches and the scenic Tafira district near the botanical garden.","food":"Papas arrugadas con mojo, sancocho and gofio escaldado; affordable idea: tapas in Vegueta, Triana or Tafira.","activities":"Vegueta, Las Canteras Beach and Jardín Botánico Viera y Clavijo; students can also explore Bandama and city cultural venues.","visitUrl":"https://www.grancanaria.com/turismo/en/the-island/municipios-de-gran-canaria/lpgrancanaria/discover-the-city","visitExtra":"https://www.spain.info/en/route/las-palmas-gran-canaria","english":"limited","englishNote":"The 2026/27 official English-course list names Big Data, 6 ECTS, autumn; Professional Skills for Engineers, 6 ECTS, autumn; and Projects of Software Engineering and Management, 3 ECTS, spring. However, EII says normal instruction is Spanish and English support is voluntary.","englishUrl":"https://www.eii.ulpgc.es/es/estudiantes/movilidad/incoming","gallery":"https://www.ulpgc.es/campus/campus-tafira","photo":{"src":"assets/campuses/ulpgc.webp","caption":"A view through the Tafira campus grounds, Las Palmas de Gran Canaria.","source":"https://commons.wikimedia.org/wiki/File:Campus_tafira_universidad_las_palmas_gran_canaria.jpg","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","author":"qdos","width":933,"height":700}},"OVI":{"setting":"city","transit":"The Los Catalanes campus is in central Oviedo; the city’s TUA urban-bus network has 13 lines, and CONECTA provides discounted regional bus and rail travel.","city":"Oviedo is a compact, pedestrian-friendly Asturian capital with pre-Romanesque heritage, a strong cider culture and a lively university atmosphere.","food":"Fabada, cachopo and cider; affordable idea: sidrerías on Calle Gascona or tapas around the old town.","activities":"Oviedo Cathedral, Fontán Market and Santa María del Naranco; Mount Naranco is a practical nearby walking and heritage excursion.","visitUrl":"https://www.visitoviedo.info/en/home","visitExtra":"https://www.turismoasturias.es/en/descubre/donde-ir/municipios/oviedo","english":"confirmed","englishNote":"The official Software Computer Engineering page says students may take first- and second-year subjects in English. Named bilingual subjects include Electronic Technology of Computers, Computer Architecture, Data Structures, Computability, Human Computer Interaction, Information Repositories and Software Process Engineering.","englishUrl":"https://www.uniovi.es/en/estudia/grados/ingenieria/informaticasoftware","gallery":"https://www.unioviedo.es/eii/","photo":{"src":"assets/campuses/ovi.webp","caption":"University of Oviedo’s historic building. The computing school is on the Los Catalanes campus.","source":"https://commons.wikimedia.org/wiki/File:Edificio_Hist%C3%B3rico_de_la_Universidad_de_Oviedo.JPG","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","author":"Sitomon","width":960,"height":640}},"ES3":{"setting":"city","transit":"Salamanca is pedestrian-friendly; city buses supplement walking. The official tourism portal links city-bus information.","city":"Salamanca is a compact World Heritage university city whose historic centre, student population and pedestrian streets create an unusually social study-abroad setting.","food":"Chanfaina, farinato and garlic soup; affordable idea: tapas around Plaza Mayor or Calle Van Dyck.","activities":"University of Salamanca, cathedral towers and Casa Lis; Barrio del Oeste adds student-oriented street art and nightlife.","visitUrl":"https://salamanca.es/en/presentation-of-the-city/practical-information","visitExtra":"https://salamanca.es/en/essential-salamanca/routes","english":"unverified","englishNote":"No individual English computing course was verified. The Faculty’s Computer Engineering degree evidence does not establish English delivery; official English-taught visiting modules identified by USAL are in Medicine and Economics, not computing.","englishUrl":"https://fciencias.usal.es/en/bachelors-degrees/bsc-computer-engineering/","gallery":"https://fciencias.usal.es/en","photo":{"src":"assets/campuses/es3.webp","caption":"Faculty of Sciences, University of Salamanca.","source":"https://commons.wikimedia.org/wiki/File:20210725_180621(0)_Ciencias_USAL_Salamanca.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"FLAVIVSAETIVS","width":525,"height":700}},"ES4":{"setting":"city","transit":"Campus Vida is in the Santiago campus area; Santiago’s urban network is TUSSA, and official exchange guidance directs students to select courses by Santiago campus and degree.","city":"Santiago is a cosmopolitan, rainy Atlantic university city centred on pilgrimage heritage, granite streets, the cathedral and a busy food market.","food":"Pulpo á feira, empanada gallega and tarta de Santiago; affordable idea: Mercado de Abastos portions or tapas on Rúa do Franco.","activities":"Cathedral and Obradoiro, Mercado de Abastos and Alameda Park; the City of Culture is an additional student destination.","visitUrl":"https://www.turismo.gal/que-visitar/cidades/santiago-de-compostela?langid=en_us&langId=en_US","visitExtra":"https://www.usc.gal/en/campus-santiago","english":"unverified","englishNote":"USC’s 2026/27 fact sheet specifies Spanish and Galician as instruction languages; USC says there is hardly any teaching in English, and the Computer Science degree lists Spanish and Galician.","englishUrl":"https://www.usc.gal/en/studies/degrees/engineering-and-architecture/computer-science-degree","gallery":"https://www.usc.gal/en/campus-santiago","photo":{"src":"assets/campuses/es4.webp","caption":"Campus Vida entrance sign, University of Santiago de Compostela.","source":"https://commons.wikimedia.org/wiki/File:2026_Letreiro_do_Campus_Vida_(Campus_Sur)._Santiago_de_Compostela._Galiza-1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Luis Miguel Bugallo Sánchez","width":433,"height":700}},"UFV":{"setting":"metro","transit":"UFV is served by public buses 657, 650A/650B, 565 and 561-series routes; Pozuelo also has Cercanías, urban/interurban buses and Metro Ligero Oeste.","city":"Pozuelo is a green, affluent Madrid suburb with extensive parks, cultural venues and rapid access to central Madrid.","food":"No specific Pozuelo food list was examined; affordable idea: municipal tapas events or Madrid tapas, not otherwise verified as everyday campus pricing.","activities":"Espacio Cultural MIRA, Parque Forestal de Somosaguas and Madrid’s Casa de Campo; the municipality also offers cinemas, sports and festivals.","visitUrl":"https://www.pozuelodealarcon.org/tu-ciudad/acerca-de-pozuelo/ocio","visitExtra":"https://www.ufv.es/en/how-to-get-to-ufv","english":"confirmed","englishNote":"UFV’s official Computer Engineering page explicitly offers a 100% English bachelor’s route. It also identifies English computing examples including Mathematics for Engineering and Discrete Mathematics; the bilingual double degree names Statistics, Modeling and Simulation, and Computer Architecture and Organization in English.","englishUrl":"https://www.ufv.es/en/study-degree-computer-engineering-madrid-spain","gallery":"https://www.ufv.es/la-universidad/conoce-la-ufv/instalaciones/","photo":{"src":"assets/campuses/ufv.webp","caption":"Student food truck on the Universidad Francisco de Vitoria campus, Pozuelo de Alarcón.","source":"https://commons.wikimedia.org/wiki/File:Foto_en_el_campus_de_la_Universidad_Francisco_de_Vitoria.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"TINOX10","width":960,"height":640}},"US1":{"setting":"town","transit":"AppalCART is fare-free and serves App State, Boone and Watauga County; Sunway/NCDOT intercity routes and Hickory Hop provide longer-distance connections.","city":"Blue Ridge scenery, Appalachian music and arts, a walkable downtown, and a strong outdoor culture define daily life.","food":"Southern cooking; seasonal farm-to-table food; affordable student option: Boone Bagelry or Melanie’s.","activities":"Blue Ridge Parkway; Grandfather Mountain; Turchin Center or Appalachian Theatre.","visitUrl":"https://www.exploreboone.com/","visitExtra":"https://www.appstate.edu/about/visit.php","english":"confirmed","englishNote":"ISEP’s English exchange profile lists Computer Science as an ideal field and gives examples including Discrete Mathematics, Introduction to Computer Applications, Data Structures and Computer Systems I; 2026-2027 App State catalog confirms CS courses.","englishUrl":"https://bulletin.appstate.edu/content.php?catoid=40&navoid=2495","gallery":"https://today.appstate.edu/2020/05/20/spring","photo":{"src":"assets/campuses/us1.webp","caption":"Sanford Mall on App State’s Boone campus in winter.","source":"https://commons.wikimedia.org/wiki/File:ASU_Sanford_Mall_Winter.JPG","license":"CC0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/deed.en","author":"Clayhefner","width":960,"height":640}},"NEIU":{"setting":"metro","transit":"CTA Brown Line to Kimball, then a CTA bus north on Kimball; Divvy has a nearby station.","city":"Residential North Park and nearby Albany Park combine tree-lined streets, diverse restaurants, parks, arts and easy access to Chicago culture.","food":"Deep-dish pizza; Italian beef; tacos in Pilsen; affordable idea: neighborhood taquerias or a Chicago hot dog.","activities":"North Park Village Nature Center; Swedish American Museum; Chicago History Museum or downtown museums.","visitUrl":"https://www.choosechicago.com/","visitExtra":"https://www.neiu.edu/about/community-and-visitor-guide","english":"confirmed","englishNote":"The English-language Computer Science catalog documents courses such as Computer Science For All and Data Structures. Ask NEIU which sections admit visiting students.","englishUrl":"https://catalog.neiu.edu/courses/cs/","gallery":"https://www.neiu.edu/about/neiu150/photo-gallery","photo":{"src":"assets/campuses/neiu.webp","caption":"Ronald Williams Library, Northeastern Illinois University main campus.","source":"https://commons.wikimedia.org/wiki/File:NEIUlibrary.jpg","license":"Public domain","licenseUrl":"","author":"User:Slo-mo","width":933,"height":700}},"US2":{"setting":"town","transit":"No named campus-serving public network was verified; official visitor information emphasizes driving and campus parking.","city":"A quiet, Catholic, suburban campus near the Back Mountain, Harveys Lake and Wilkes-Barre; local life centers on small restaurants, lakes, trails and community events.","food":"Grotto Pizza; pierogies; Italian food; affordable ideas: J&J Deli, Pizza Bella or the Back Mountain Farmers Market.","activities":"Harveys Lake; Ricketts Glen State Park; Wilkes-Barre’s F.M. Kirby Center or River Common.","visitUrl":"https://discovernepa.com/regions/valley-communities/back-mountain","visitExtra":"https://www.misericordia.edu/admissions/visit","english":"confirmed","englishNote":"The undergraduate Computer Science catalog and English admission requirements support computing instruction in English. Confirm which courses are open to visiting students.","englishUrl":"https://catalog.misericordia.edu/content.php?catoid=11&navoid=792","gallery":"https://www.misericordia.edu/campus-map","photo":{"src":"assets/campuses/us2.webp","caption":"Bell tower, Misericordia University campus in Dallas, Pennsylvania.","source":"https://commons.wikimedia.org/wiki/File:Bell_Tower_Misericordia_University_exterior_01.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"DutchTreat","width":960,"height":678}},"US3":{"setting":"town","transit":"UCM’s free Night Ryder serves campus, residences, Walmart, Walgreens and downtown; Amtrak’s Missouri River Runner stops downtown.","city":"A walkable, friendly college town with downtown five minutes from campus, local festivals, murals, student arts and easy Kansas City access.","food":"Fresh doughnuts from Yummy’s; Missouri-grown farmers-market produce; affordable campus choices include Einstein Bagel, Taco Bell or Spin! Pizza.","activities":"UCM Gallery of Art & Design; Pertle Springs; Walton Stadium or downtown murals and festivals.","visitUrl":"https://www.visitwarrensburg.com/","visitExtra":"https://www.ucmo.edu/about/locations/ucm-warrensburg-campus/index.php","english":"confirmed","englishNote":"UCM’s English-language catalog includes Python Programming I and Computer Science courses. Confirm exchange eligibility, prerequisites and the actual timetable.","englishUrl":"https://catalog.ucmo.edu/preview_entity.php?catoid=23&ent_oid=658","gallery":"https://www.ucmo.edu/about/locations/ucm-warrensburg-campus/warrensburg-campus-map/index.php"},"US4":{"setting":"metro","transit":"VIA Metropolitan Transit Routes 8 and 14 serve the UIW area; UIW students, faculty and staff have had VIA U-Pass access.","city":"San Antonio blends Catholic heritage, Mexican-American culture, missions, museums, River Walk life and a major food scene; UIW also has historic headwaters and sanctuary grounds.","food":"Breakfast tacos; puffy tacos; barbecue; affordable idea: free River Walk plus inexpensive taqueria or food-truck meal.","activities":"San Antonio River Walk; San Antonio Missions National Historical Park; Pearl District or Brackenridge Park.","visitUrl":"https://www.visitsanantonio.com/","visitExtra":"https://www.uiw.edu/about/uiw-san-antonio.html","english":"confirmed","englishNote":"UIW’s incoming exchange factsheet specifies Fall 2026 and Spring 2027, language of instruction English, undergraduate access to the School of Mathematics, Sciences and Engineering, and course listings via Academic Programs/Search a Course; UIW’s exchange search includes CIS and Computer Science examples.","englishUrl":"https://uiw.smartcatalogiq.com/en/2026-2027/undergraduate-catalog/course-descriptions","gallery":"https://www.uiw.edu/","photo":{"src":"assets/campuses/us4.webp","caption":"McDermott Center, University of the Incarnate Word in San Antonio.","source":"https://commons.wikimedia.org/wiki/File:McDermott_Center,_University_of_the_Incarnate_Word,_San_Antonio,_TX.jpg","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","author":"Zereshk","width":933,"height":700}},"US5":{"setting":"town","transit":"Kenosha Transit Route 1 serves Parkside; UW-Parkside states Route 1 stops at campus, with service approximately 4:55 a.m.–6:35 p.m. daily.","city":"Prairie-and-woodland campus life is paired with Kenosha’s Lake Michigan harbor, museums, lighthouses, streetcars, public art and easy regional access.","food":"Wisconsin cheese curds; bratwurst; Friday fish fry; affordable ideas: Public Brewing cheese curds, Brat Stop or Kenosha’s budget FUN 101 list.","activities":"Electric Streetcar; Southport Lighthouse; Kenosha museums, HarborPark or Lake Michigan beaches.","visitUrl":"https://www.visitkenosha.com/","visitExtra":"https://www.uwp.edu/visit/","english":"confirmed","englishNote":"Parkside’s English-language computing catalog includes Introduction to Programming and Data Structures. Confirm exchange enrollment and section availability.","englishUrl":"https://catalog.uwp.edu/course-descriptions/csci","gallery":"https://archives.uwp.edu/exhibits/show/uwp_photos/arch","photo":{"src":"assets/campuses/us5.webp","caption":"University of Wisconsin–Parkside Student Center.","source":"https://commons.wikimedia.org/wiki/File:University_of_Wisconsin-Parkside_Student_Center.jpg","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","author":"Tallisguy00","width":933,"height":700}},"HEPL":{"setting":"city","transit":"HEPL Parc des Marêts: TEC buses 9, 40, 41, 43, 47, 50, 89, 91 and 194; Seraing station is about 10 minutes on foot.","city":"Seraing is an industrial Liège-conurbation city with student access to Liège’s nightlife and cultural centre; Parc des Marêts is the named computing campus.","food":"Not examined in the retrieved official evidence; campus surroundings have low-cost food shops and a campus restaurant.","activities":"Val-Saint-Lambert Museum; Château Cockerill; Fort de Boncelles.","visitUrl":"https://www.visitezliege.be/fr/page/seraing","visitExtra":"https://www.visitezliege.be/en/page/ou-boire-et-manger-a-liege","english":"limited","englishNote":"The incoming list identifies English computing units including Network Security and Cloud Computing. Verify the qualification level and eligibility for a bachelor’s exchange before relying on these modules.","englishUrl":"https://www.hepl.be/fr/international/venir-etudier-hepl","gallery":"https://www.hepl.be/fr/campus/parc-marets","photo":{"src":"assets/campuses/hepl.webp","caption":"HEPL’s Site Gloesener in Liège. Verify the module location if assigned to Seraing.","source":"https://commons.wikimedia.org/wiki/File:Haute_Ecole_de_la_Province_de_Li%C3%A8ge_-_Site_Gloesener.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Éric Dodémont ( Dodeeric )","width":960,"height":539}},"IMT":{"setting":"town","transit":"No campus-specific public-transit service was verified; official material places Campus Jarlard in Albi.","city":"Albi is a UNESCO Episcopal City of red-brick streets, with Toulouse-Lautrec’s museum, Tarn riverbanks and a compact, walkable historic centre.","food":"Not examined in the retrieved official evidence; use campus or city-market options pending local price checking.","activities":"Sainte-Cécile Cathedral; Toulouse-Lautrec Museum; Green Escape urban trail.","visitUrl":"https://www.albi-tourisme.fr/en/discover-albi","visitExtra":"https://www.albi-tourisme.fr/en/pratique/venir-a-albi/mobilite-douce","english":"limited","englishNote":"The 2026 English Tracks are partner-nominated, September–February, 30 ECTS and fully English, but the named tracks are renewable energy, transport materials, industrial organisation and pharmaceutical/agrifood/cosmetics—not a computing track; one partial computing-adjacent item is ERP and Enterprise Information Systems.","englishUrl":"https://www.imt-mines-albi.fr/en/study-engineering-in-english","gallery":"https://www.imt-mines-albi.fr/fr/ecole-ingenieur/campus-environnement-logements-et-residences"},"LEM":{"setting":"city","transit":"Le Mans campus is served by tram T1; the station is about 20 minutes on foot and buses connect station and campus.","city":"Le Mans combines the medieval Cité Plantagenêt, university associations and a strong motorsport identity; SETRAM makes the suburban campus practical.","food":"Rillettes du Mans; Sablé shortbread; affordable idea: buy a jar of rillettes or biscuits from a market/delicatessen.","activities":"Cité Plantagenêt; 24 Hours of Le Mans circuit; Night of the Chimeras.","visitUrl":"https://www.lemans-tourisme.com/en/practical-information/come-to-le-mans.html","visitExtra":"https://www.lemans-tourisme.com/en/en-image","english":"unverified","englishNote":"No exact English-taught incoming computing course was verified. The 2026/27 international guide documents exchange support and language classes, while the official Computer Science programme evidence retrieved was French-language only.","englishUrl":"https://www.univ-lemans.fr/en/international/coming-to-study-at-le-mans-university.html","gallery":"https://www.univ-lemans.fr/fr/vie-des-campus.html","photo":{"src":"assets/campuses/lem.webp","caption":"Humanities building, Le Mans Université campus.","source":"https://commons.wikimedia.org/wiki/File:Batiment_lettres_universit%C3%A9_du_Mans.JPG","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/","author":"Trowa Barton","width":927,"height":700}},"REI":{"setting":"city","transit":"Moulin de la Housse is served within Reims’s Grand Reims Mobilités bus-and-tram network; buses and trams generally operate 05:15–00:25.","city":"Reims is a compact City of Art and History: cathedral, Art Deco centre, museums, champagne cellars and student cultural events shape everyday life.","food":"Biscuit rose de Reims; champagne; affordable idea: Boulingrin Market picnic supplies and a Fossier biscuit tasting.","activities":"Notre-Dame Cathedral; Saint-Remi Basilica and museum; Champagne-cellar visit.","visitUrl":"https://www.reims-tourisme.com/en/explore-the-city/top-10-attractions","visitExtra":"https://www.reims-tourisme.com/en/organize/access-and-transport/getting-around-reims","english":"limited","englishNote":"URCA’s 2026–27 fact sheet explicitly says no programmes are taught completely in English; no individual English computing course was verified in the retrieved evidence. The relevant incoming course catalogue is the official URCA catalogue portal.","englishUrl":"https://www.univ-reims.fr/formation/catalogue-de-formation/catalogue-de-formation,23515,38948.html","gallery":"https://www.univ-reims.fr/eisine/contact-acces/plan-du-campus-moulin-de-la-housse/plan-du-campus,23509,38938.html","photo":{"src":"assets/campuses/rei.webp","caption":"Lecture halls on the Moulin de la Housse campus, Reims.","source":"https://commons.wikimedia.org/wiki/File:Moulin_de_la_housse_152817.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Gérald Garitan","width":960,"height":331}},"PAR":{"setting":"city","transit":"Parco Area delle Scienze is served by Parma’s TEP bus network, including campus services and Campus Express; night lines also cover the Science and Technology Campus.","city":"Parma is a walkable UNESCO Creative City of Gastronomy, pairing historic monuments and opera with a large, green science campus south of the centre.","food":"Prosciutto di Parma; Parmigiano Reggiano; tortelli d’erbetta; affordable idea: deli portions or a market picnic rather than a restaurant.","activities":"Parma Cathedral and Baptistery; Palazzo della Pilotta; Parco Ducale.","visitUrl":"https://www.visit-parma.com/en/things-to-do","visitExtra":"https://parmawelcome.it/en","english":"limited","englishNote":"Official 2026/27 computing-unit records retrieved for Computer Science and Computer Engineering identify Computer Science and Programming Laboratory, Paradigms and Languages for Data Analysis, and Computer Architecture as Italian-taught; the exchange page confirms that English course units exist generally, not specifically in computing.","englishUrl":"https://www.unipr.it/en/study-parma","gallery":"https://www.unipr.it/en/science-and-technology-campus","photo":{"src":"assets/campuses/par.webp","caption":"University of Parma’s historic Palazzo dell’Università. The science campus is at Parco Area delle Scienze.","source":"https://commons.wikimedia.org/wiki/File:Palazzo_dell%27Universit%C3%A0_(Parma)_-_facciata_2017-04-06.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Parma1983","width":522,"height":700}},"SAS":{"setting":"city","transit":"The retrieved evidence identifies ATP as Sassari’s city public-transport operator; no official campus-to-stop detail was verified.","city":"Sassari is Sardinia’s second-largest city, with a historic centre, Spanish-Catalan traces, traditional festivals and easy access to northern Sardinian coast and countryside.","food":"Not examined in the retrieved official evidence; local-food detail was not verified from an official tourism source.","activities":"Cathedral of St Nicholas; Rosello Fountain; Museo Nazionale G. A. Sanna.","visitUrl":"https://www.sardegnaturismo.it/en/explore/sassari","visitExtra":"https://www.italia.it/en/sardinia/sassari","english":"unverified","englishNote":"The official Sassari Computer Engineering catalogue lists Data Structures and Algorithms, Computer Architectures, Operating Systems, Computer Networks, Databases and Web Technologies, Visual Computing and Digital Security, but the retrieved record does not state their teaching language or incoming-exchange availability.","englishUrl":"https://unifind.uniss.it/resource/cds/10796?language=en-US","gallery":"https://www.uniss.it/en","photo":{"src":"assets/campuses/sas.webp","caption":"University of Sassari’s historic building at Piazza Università. Class locations vary by department.","source":"https://commons.wikimedia.org/wiki/File:Universit%C3%A4t_Piazza_Universita_Sassari.JPG","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"Herbert wie","width":933,"height":700}},"RTD":{"setting":"metro","transit":"Wijnhaven 107 is in central Rotterdam; RET provides the city’s buses, trams and metro, and Rotterdam UAS lists the Wijnhaven location.","city":"Rotterdam is a dense, international port city where architecture, waterfronts, museums, markets and cycling shape student life.","food":"Herring sandwich; stroopwafel; affordable idea: Markthal or Binnenrotte market stalls.","activities":"Cube Houses and Markthal; Royal Spido harbour tour; Kinderdijk windmills.","visitUrl":"https://www.rotterdam.info/en/top-10-things-to-do-in-rotterdam","visitExtra":"https://www.rotterdamuas.com/go/living-in-rotterdam/starting-out/public-transport","english":"confirmed","englishNote":"The official Rotterdam UAS exchange catalogue lists Data Science Exchange; its location is Wijnhaven 107, it targets Computer Science/IT or related STEM students, and all classes are in English, with expected English around CEFR B2.","englishUrl":"https://www.rotterdamuas.com/programmes/exchange/Data-science/","gallery":"https://www.rotterdamuas.com/about/locations/wijnhaven-107","photo":{"src":"assets/campuses/rtd.webp","caption":"Rotterdam University of Applied Sciences building. Check the Wijnhaven site for computing modules.","source":"https://commons.wikimedia.org/wiki/File:Rotterdam_-_Hogeschool_Rotterdam.jpg","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","author":"Fred Romero from Paris, France","width":960,"height":640}},"FHNW":{"setting":"town","transit":"FHNW Campus Brugg-Windisch is a two-minute walk from Brugg railway station; the campus is in Windisch.","city":"Brugg-Windisch is a small, rail-connected academic setting rather than a major urban centre, with campus restaurant, café, library and nearby regional-city access.","food":"Not examined in the retrieved official evidence; local-food detail was not verified from an official tourism source.","activities":"Not examined in the retrieved official evidence; the official campus gallery confirms campus visuals but not student attractions.","visitUrl":"https://www.fhnw.ch/en/about-fhnw/locations/brugg-windisch","visitExtra":"https://www.fhnw.ch/en/news-events/media-corner/picture-gallery","english":"confirmed","englishNote":"FHNW’s incoming-student page confirms modules taught in English and an International Track in Computer Science; the official degree page gives English examples including programming, software engineering and computer graphics at Brugg-Windisch.","englishUrl":"https://www.fhnw.ch/en/computer-science/degree-programmes/offerings","gallery":"https://www.fhnw.ch/en/news-events/media-corner/picture-gallery","photo":{"src":"assets/campuses/fhnw.webp","caption":"FHNW Campus Brugg-Windisch.","source":"https://commons.wikimedia.org/wiki/File:FHNW_Campus_Brugg_Windisch.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","author":"FHNWStabKom","width":960,"height":640}}},"countries":{"Belgium":{"note":"Belgium has Dutch, French and German as official languages. French is the everyday language around Liège and Seraing. Bakeries, cafés and markets are good places to try local specialties such as Liège waffles. Rail is useful for weekends in other Belgian cities.","url":"https://www.belgium.be/en/about_belgium/tourism"},"France":{"note":"France's official tourism site highlights varied regional identities, landscapes and culinary traditions from cities to mountains and coast. Meals are often shared unhurriedly, and regional specialties differ by area. Public transit and high-speed trains make regional travel practical. Tip: check your study city's official language context, look for university welcome weeks and language exchanges to meet people.","url":"https://www.france.fr/en"},"Germany":{"note":"Germany's official tourist board showcases cities, culture, nature and regional experiences across the country. Regional cuisine varies widely — from bread-and-sausage traditions to Alpine and coastal dishes — and everyday life is fairly structured around schedules. The dense rail and transit network supports regional exploration. Tip: university sports courses (Hochschulsport) and intercultural meetups are common ways to meet people.","url":"https://www.germany.travel/en/home.html"},"Italy":{"note":"Italy's official tourism portal organizes the country by regions, each with distinct villages, landscapes, gastronomy and cultural heritage. Meals are a social centerpiece, and regional dishes differ strongly from north to south. Regional trains and city buses are the usual student transport. Tip: university erasmus-style associations and local feste are reliable, informal ways to meet classmates.","url":"https://www.italia.it/en"},"Netherlands":{"note":"Cycling and rail are practical ways to get around, especially around Rotterdam. Dutch is the national language and student-facing programs often also use English. Rotterdam offers architecture, markets and a port-city food scene. University associations and shared meals are often good ways to meet people.","url":"https://www.holland.com"},"Spain":{"note":"Spain's official tourism website presents regional diversity — cities, coastlines, festivals and gastronomy that change by autonomous community. Mealtimes run later than many visitors expect, and shared tapas-style eating is common. Metro and cercanías networks serve most study cities. Tip: look for university buddy programs and language exchanges (intercambio) to build a circle quickly.","url":"https://www.spain.info/en"},"Switzerland":{"note":"Language and daily routines vary by canton. German is the main written language around Brugg-Windisch and Swiss German is common in conversation. Regional dishes, hiking and lakeside outings make useful weekend plans. Check student transit fares and association events before arrival.","url":"https://www.myswitzerland.com"},"United States":{"note":"Campus life varies across the six study locations. Orientation, clubs and sports can help you meet people, and the international office can explain local transport and student services. Chicago has an extensive transit network. Smaller college towns can have good campus buses and fewer options for regional trips.","url":"https://www.thebrandusa.com/"}},"careers":{"Belgium":{"currency":"EUR","bands":{"junior":[31200,38400],"mid":[42000,54000],"senior":[48000,66000]},"salaryNote":"Software developer/engineer; Hays Belgium 2026 figures relayed as gross monthly €2600–3200 junior, €3500–4500 mid (3–5 years), €4000–5500 senior (5+); converted ×12; national, base/gross, not total compensation.","salaryUrl":"https://www.hays.be/en/salary-guide","salaryExtra":"https://ruicodex.com/Blog/Detail/2026-belgian-tech-salary-report-what-software-developers-really-earn","freelance":{"low":70,"high":70,"unit":"hour","currency":"EUR","note":"SThree’s Belgian Java and .NET contract benchmark averaged €70/hour in its 2022 mission data. This is an older specialist reference. The 2025 Belgian freelancer survey provides broader context across professions.","url":"https://www.sthree.com/en-be/insights-and-research/the-future-of-work/stem-market-in-belgium-the-best-sectors-and-rates-for-freelancers","extra":"https://freelancersinbelgium.be/wp-content/uploads/2025/09/V4-Report-Freelancing-in-Belgium_-Trends-Insights-2025.pdf"},"workNote":"Non-EU students considering independent activity in Belgium should check professional-card rules and any regional exceptions. Seraing and Liège are in Wallonia. The commonly cited student employee hours do not settle independent work.","visaUrl":"https://home-affairs.ec.europa.eu/policies/migration-and-asylum/eu-immigration-portal/student-belgium_en","visaExtra":"https://emploi.wallonie.be/home/travailleurs-etrangers/carte-professionnelle.html"},"Germany":{"currency":"EUR","bands":{"junior":[55000,65000],"mid":[65000,75000],"senior":[75000,95000]},"salaryNote":"Software developer; national gross annual employee salary, DEVjobs.de 1–3 years €55000–65000 and 3–5 years €65000–75000; senior 5+ range cross-checked against 2026 market guide; base/gross, not total compensation.","salaryUrl":"https://en.devjobs.de/artikel/software-entwickler-gehalt-in-deutschland-eine-umfassende-analyse","salaryExtra":"https://www.inedjobs.com/2026/06/software-engineer-salary-germany-2026.html","freelance":{"low":90,"high":90,"unit":"hour","currency":"EUR","note":"Software and web-development freelance median, DACH Freelancer-Kompass 2026; survey of 1310 freelancers conducted Jan–Feb 2026, covering Germany, Austria and Switzerland rather than Germany alone.","url":"https://www.freelancermap.com/files/survey/freelancer-study-2026-DACH-region.pdf"},"workNote":"Third-country students may work 140 full or 280 half days annually, but any self-employed activity requires approval from the competent foreigners authority; approval is case-specific and must not jeopardize study.","visaUrl":"https://www.make-it-in-germany.com/en/study-vocational-training/studying-in-germany/work","visaExtra":"https://www.make-it-in-germany.com/en/study-vocational-training/studies-in-germany/work/print"},"Netherlands":{"currency":"EUR","bands":{"junior":[44000,44000],"mid":[60000,60000],"senior":[79000,79000]},"salaryNote":"Software/data/cloud/AI engineer salary expectations; Chase IT Recruitment conversations with 133 engineers, national Netherlands, 2026; medians annualized using 12.96 months including 8% holiday allowance, so low=high is a reported median rather than a range.","salaryUrl":"https://chaseitrecruitment.nl/kennis/tech-hiring-statistics-netherlands-2026","salaryExtra":"https://www.payscale.com/research/NL/Job=Software_Developer/Salary","freelance":{"low":89,"high":107,"unit":"hour","currency":"EUR","note":"Freelance developer development/implementation rates in the Netherlands, Q1 2026: client offered €89/hour and freelancers asked €107/hour, excluding VAT; observed local market index, not experience-specific.","url":"https://vbsmarketing.eu/en/guides/freelance-developer-rates-netherlands"},"workNote":"A student may work self-employed without a TWV while continuing to meet the conditions of the study residence permit; paid employment has separate TWV and hour restrictions.","visaUrl":"https://home-affairs.ec.europa.eu/policies/migration-and-asylum/eu-immigration-portal/student-netherlands_en?prefLang=mt","visaExtra":"https://ind.nl/en/residence-permits/study/student-residence-permit-for-university-or-higher-professional-education"},"Switzerland":{"currency":"CHF","bands":{"junior":[75000,95000],"mid":[95000,120000],"senior":[120000,150000]},"salaryNote":"Software developer; national gross annual median bands, 2026: junior 0–2 years CHF75000–95000, intermediate 3–5 years CHF95000–120000, senior 6–10 years CHF120000–150000; base/gross, not total compensation.","salaryUrl":"https://www.agences-placement.ch/en/blog/salaire-developpeur-informatique-suisse","salaryExtra":"https://www.salaryexpert.com/salary/job/software-developer/switzerland","freelance":{"low":760,"high":853,"unit":"day","currency":"EUR","note":"Independent-platform observed Swiss freelancer rates as of 20 Nov 2026: web developer average €760/day and software developer average €853/day; FRATCH live freelancer benchmark, 8-hour day, not a seniority range and reported in EUR.","url":"https://fratch.io/en/role/software-developer/switzerland/rate-benchmark"},"workNote":"For non-EU/EFTA nationals, self-employment requires labour-market review and authorization; student work is limited to 15 hours weekly after six months and requires university confirmation that studies remain on track.","visaUrl":"https://www.sem.admin.ch/sem/en/home/themen/arbeit/faq.html","visaExtra":"https://www.kmu.admin.ch/en/foreign-national-setting-up-a-business"},"France":{"currency":"EUR","bands":{"junior":[51342,51342],"mid":[60000,60000],"senior":[75000,75000]},"salaryNote":"France, gross annual employee pay. Junior is ERI’s 2026 employer-survey entry average (1–3 years). Mid-level and senior are Bluecoders placement medians (2–5 years and 5+ years), Aug 2025–Aug 2026. These are points from different samples.","salaryUrl":"https://www.bluecoders.com/en/ressources/barometre-salaires-tech-ingenieurs","salaryExtra":"https://www.salaryexpert.com/salary/job/software-developer/france","freelance":{"low":300,"high":535,"unit":"day","currency":"EUR","note":"Malt France front-end developer billing averages across experience tiers. About €300/day at 0–2 years, €407/day at 3–7, and €535/day at 8–15. Platform reference reviewed November 2026; fees and taxes are separate.","url":"https://www.malt.fr/t/barometre-tarifs/tech/developpeur-frontend"},"workNote":"Service Public says a foreign national studying in France on a student residence permit cannot combine that status with micro-entrepreneur status. A different residence title may be required for independent professional activity.","visaUrl":"https://entreprendre.service-public.gouv.fr/vosdroits/F36612","visaExtra":"https://www.service-public.fr/particuliers/vosdroits/F35795"},"Italy":{"currency":"EUR","bands":{"junior":[27500,27500],"mid":[32500,42500],"senior":[47500,57500]},"salaryNote":"EgoValeo Software Engineer, Italy, November 2026. Gross annual RAL. Figures are the middle half of pay within each published level (P25 to P75); junior endpoints are both €27,500. The source classifies seniority by level.","salaryUrl":"https://it.egovaleo.com/ats-ev/salary-benchmark/software-engineer-1/","salaryExtra":"https://it.egovaleo.com/geek-lab/software-developer/","freelance":{"low":470,"high":550,"unit":"day","currency":"EUR","note":"Software Developer contractor benchmark in Italy, 2026; TalentUp local-market contractor data, €470–€550/day and €59–€69/hour.","url":"https://talentup.io/insights/contractors-benchmark-report/italy"},"workNote":"Italian public administration guidance gives a study-to-self-employment permit conversion procedure. The EU student portal separately describes employee work limits. Confirm the applicable route before opening a partita IVA or accepting independent contracts.","visaUrl":"https://home-affairs.ec.europa.eu/policies/migration-and-asylum/eu-immigration-portal/student-italy_en","visaExtra":"https://www2.immigrazione.regione.toscana.it/?q=node/6224"},"Spain":{"currency":"EUR","bands":{"junior":[28000,38000],"mid":[42000,55000],"senior":[55000,70000]},"salaryNote":"Adecco 2026 Spain salary guide, Full Stack Developer gross annual pay. Junior, mid-level and senior are the guide’s role bands. Figures vary by stack and region.","salaryUrl":"https://www.adecco.com/-/jssmedia/project/adecco/adecco-es/guia-salarial/pdf/GGSS-2026-COMPLETA_ES-.pdf","salaryExtra":"https://www.getmanfred.com/tech-career-report","freelance":{"low":313,"high":313,"unit":"day","currency":"EUR","note":"Software-development freelancer rate on Malt, Spain platform average over the trailing three months to 24 September 2026; €313/day is an observed marketplace average, not a published low–high range.","url":"https://kettlehour.com/freelance/european-union.html"},"workNote":"For a long-term higher-education study authorization, Spain’s official guidance says work on one’s own account or for an employer is automatic when compatible with studies and limited to 30 hours/week; other study categories can require authorization. The cited official material does not specifically settle overseas-client remote services, so the permit type and work arrangement must be checked.","visaUrl":"https://inclusion.gob.es/en/web/migraciones/w/hoja-4-bis-acceso-al-empleo-de-las-personas-titulares-de-una-autorizacion-de-estancia-de-larga-duracion-por-estudios-movilidad-de-alumnos-servicios-de-voluntariado-o-actividades-formativas","visaExtra":"https://inclusion.gob.es/en/web/migraciones/cuenta-propia-/-emprendedores"},"United States":{"currency":"USD","bands":{"junior":[85000,115000],"mid":[115000,155000],"senior":[150000,200000]},"salaryNote":"Software Engineer, national United States, 2026; KORE1 base-salary guide exact bands: 0–2, 2–4 and 4–7 years; excludes typical total compensation from the salary cells.","salaryUrl":"https://www.kore1.com/software-engineer-salary-guide","salaryExtra":"https://www.bls.gov/ooh/computer-and-information-technology/software-developers.htm","freelance":{"low":35,"high":55,"unit":"hour","currency":"USD","note":"Independent web-developer direct-client rates, United States, 2025 survey basis reported in a 2026 benchmark: junior 0–2 years $35–$55/hour, mid 2–5 years $55–$100/hour, senior 5+ years $100–$160+/hour; platform rates may be 20–40% lower.","url":"https://solohourly.com/rates/web-developer-rates-in-united-states"},"workNote":"F-1 students need the applicable employment authorization. DHS treats starting a business as work and discusses it under authorized OPT related to the program. J-1 exchange students should ask their program sponsor about their separate authorization rules.","visaUrl":"https://www.uscis.gov/i-9-central/form-i-9-resources/handbook-for-employers-m-274/70-evidence-of-employment-authorization-for-certain-categories/74-exchange-visitors-and-students/742-f-1-and-m-1-nonimmigrant-students","visaExtra":"https://fam.state.gov/FAM/09FAM/09FAM040205.html"}}};
